function db(){static $p;if($p instanceof PDO)return $p;$p=new PDO('mysql:host='.DB_HOST.';dbname='.DB_NAME.';charset=utf8mb4',DB_USER,DB_PASS,[PDO::ATTR_ERRMODE=>PDO::ERRMODE_EXCEPTION,PDO::ATTR_DEFAULT_FETCH_MODE=>PDO::FETCH_ASSOC]);return $p;}
function q($s,$a=[]){$x=db()->prepare($s);$x->execute($a);return $x;} function one($s,$a=[]){return q($s,$a)->fetch();} function all($s,$a=[]){return q($s,$a)->fetchAll();} function val($s,$a=[]){return q($s,$a)->fetchColumn();}
function e($v){return htmlspecialchars((string)$v,ENT_QUOTES,'UTF-8');} function now(){return time();} function me(){return (int)($_SESSION['uid']??0);} function needLogin(){if(!me()){header('Location: index.php');exit;}}
function flash($m,$t='ok'){$_SESSION['flash']=['m'=>$m,'t'=>$t];} function takeFlash(){$f=$_SESSION['flash']??null;unset($_SESSION['flash']);return $f;}
function tribes(){return [1=>'Roman',2=>'Teuton',3=>'Gaul'];}
function buildingDefs(){return [
15=>['name'=>'Main Building','base'=>[70,40,60,20],'req'=>[],'time'=>30],10=>['name'=>'Warehouse','base'=>[130,160,90,40],'req'=>[],'time'=>45],11=>['name'=>'Granary','base'=>[80,100,70,20],'req'=>[],'time'=>40],17=>['name'=>'Marketplace','base'=>[80,70,120,70],'req'=>[15=>3],'time'=>55],18=>['name'=>'Embassy','base'=>[220,160,90,40],'req'=>[15=>1],'time'=>70],19=>['name'=>'Barracks','base'=>[210,140,260,120],'req'=>[15=>3],'time'=>75],20=>['name'=>'Stable','base'=>[260,140,220,100],'req'=>[19=>3],'time'=>90],21=>['name'=>'Workshop','base'=>[460,510,600,320],'req'=>[15=>5],'time'=>120],22=>['name'=>'Academy','base'=>[220,160,90,40],'req'=>[15=>3],'time'=>80],23=>['name'=>'Smithy','base'=>[170,200,380,130],'req'=>[22=>3],'time'=>85],24=>['name'=>'Town Hall','base'=>[1250,1110,1260,600],'req'=>[15=>10],'time'=>180],25=>['name'=>'Residence','base'=>[580,460,350,180],'req'=>[15=>5],'time'=>120],26=>['name'=>'Palace','base'=>[550,800,750,250],'req'=>[15=>5],'time'=>150],27=>['name'=>'Rally Point','base'=>[110,160,90,70],'req'=>[],'time'=>55],28=>['name'=>'Wall','base'=>[160,100,210,50],'req'=>[],'time'=>60],29=>['name'=>'Cranny','base'=>[40,50,30,10],'req'=>[],'time'=>25],30=>['name'=>'Sawmill','base'=>[520,380,290,90],'req'=>[15=>5],'time'=>100],31=>['name'=>'Brickyard','base'=>[440,480,320,50],'req'=>[15=>5],'time'=>100],32=>['name'=>'Iron Foundry','base'=>[400,350,520,100],'req'=>[15=>5],'time'=>100],33=>['name'=>'Grain Mill','base'=>[500,440,380,0],'req'=>[15=>5],'time'=>100]];}
