function world(){static $w;if(!$w)$w=one('SELECT * FROM op_worlds WHERE id=1');return $w;}
function prod($v){$p=[30,30,30,20];foreach(all('SELECT type,level FROM op_fields WHERE village_id=?',[$v['id']]) as $f)$p[(int)$f['type']-1]+=30*pow(1.25,max(0,(int)$f['level']-1));$p[3]-=(int)$v['population']+(int)$v['crop_upkeep'];return $p;}
function sync($vid){$v=one('SELECT * FROM op_villages WHERE id=?',[$vid]);if(!$v)return;$t=now();$dt=max(0,$t-(int)$v['last_tick']);if($dt){$p=prod($v);$r=['wood'=>$p[0],'clay'=>$p[1],'iron'=>$p[2],'crop'=>$p[3]];$set=[];$a=[];foreach($r as $k=>$rate){$cap=$k==='crop'?$v['granary_cap']:$v['warehouse_cap'];$set[]="$k=?";$a[]=max(0,min($cap,(float)$v[$k]+$rate*$dt/3600));}$set[]='last_tick=?';$a[]=$t;$a[]=$vid;q('UPDATE op_villages SET '.implode(',',$set).' WHERE id=?',$a);}
 foreach(all('SELECT * FROM op_build_queue WHERE village_id=? AND finish_at<=? ORDER BY finish_at,id',[$vid,$t]) as $b){$table=(int)$b['action_type']?'op_fields':'op_buildings';q("UPDATE $table SET type=?,level=? WHERE village_id=? AND slot=?",[$b['building_type'],$b['level'],$vid,$b['slot']]);q('UPDATE op_villages SET population=population+1 WHERE id=?',[$vid]);q('DELETE FROM op_build_queue WHERE id=?',[$b['id']]);}}
function currentVillage(){needLogin();$v=one('SELECT * FROM op_villages WHERE id=? AND owner_id=?',[($_SESSION['village_id']??0),me()]);if(!$v)$v=one('SELECT * FROM op_villages WHERE owner_id=? ORDER BY id LIMIT 1',[me()]);if(!$v){session_destroy();header('Location: index.php');exit;}$_SESSION['village_id']=$v['id'];sync($v['id']);return one('SELECT * FROM op_villages WHERE id=?',[$v['id']]);}
function cost($type,$level){$d=buildingDefs()[$type]??null;if(!$d)return null;$f=pow(1.28,max(0,$level-1));return ['wood'=>(int)ceil($d['base'][0]*$f),'clay'=>(int)ceil($d['base'][1]*$f),'iron'=>(int)ceil($d['base'][2]*$f),'crop'=>(int)ceil($d['base'][3]*$f)];}
function queueBuild($v,$slot,$type,$level,$field){$c=cost($type,$level);foreach($c as $r=>$n)if($v[$r]<$n)throw new Exception('Niet genoeg grondstoffen.');if($field&&(int)val('SELECT COUNT(*) FROM op_build_queue WHERE village_id=? AND action_type=1',[$v['id']])>=2)throw new Exception('Veldenbouwqueue is vol.');if(!$field&&(int)val('SELECT COUNT(*) FROM op_build_queue WHERE village_id=? AND action_type=0',[$v['id']])>=1)throw new Exception('Gebouwenqueue is vol.');foreach($c as $r=>$n)q("UPDATE op_villages SET $r=$r-? WHERE id=?",[$n,$v['id']]);$last=(int)val('SELECT COALESCE(MAX(finish_at),0) FROM op_build_queue WHERE village_id=?',[$v['id']]);$start=max(now(),$last);$dur=(int)ceil((buildingDefs()[$type]['time']*pow(1.28,$level-1))/max(.1,(float)world()['speed']));q('INSERT INTO op_build_queue(village_id,slot,building_type,level,action_type,start_at,finish_at) VALUES(?,?,?,?,?,?,?)',[$v['id'],$slot,$type,$level,$field?1:0,$start,$start+$dur]);}
function logout(){session_destroy();header('Location: index.php');exit;}
